@group(0) @binding(0) var<storage, read_write> dat: array<vec2<f32>>;
const NN: u32 = 8u;
var<workgroup> buf: array<vec2<f32>, 16u>;
const PI: f32 = 3.1415926535897932;
@compute @workgroup_size(32)
fn main(@builtin(workgroup_id) wgid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {
  let line: u32 = wgid.x;
  let tid: u32 = lid.x;
  let base: u32 = line * NN;
  for (var idx: u32 = tid; idx < NN; idx = idx + 32u) { buf[idx] = dat[base + idx]; }
  var src: u32 = 0u;
  var dst: u32 = 8u;
  var p: u32 = 1u;
  for (var s: u32 = 0u; s < 3u; s = s + 1u) {
    workgroupBarrier();
    for (var i: u32 = tid; i < 4u; i = i + 32u) {
      let k: u32 = i & (p - 1u);
      let j: u32 = ((i - k) << 1u) + k;
      let u0: vec2<f32> = buf[src + i];
      let u1: vec2<f32> = buf[src + i + 4u];
      let ang: f32 = -PI * f32(k) / f32(p);
      let wc: f32 = cos(ang);
      let ws: f32 = sin(ang);
      let t: vec2<f32> = vec2<f32>(wc * u1.x - ws * u1.y, wc * u1.y + ws * u1.x);
      buf[dst + j] = u0 + t;
      buf[dst + j + p] = u0 - t;
    }
    p = p << 1u;
    let tmp: u32 = src; src = dst; dst = tmp;
  }
  workgroupBarrier();
  for (var idx: u32 = tid; idx < NN; idx = idx + 32u) { dat[base + idx] = buf[src + idx]; }
}

