      let t: vec2<f32> = vec2<f32>(wc * u1.x - ws * u1.y, wc * u1.y + ws * u1.x);
      buf[dst + j] = u0 + t;
      buf[dst + j + p] = u0 - t;
    }
    p = p << 1u;
    let tmp: u32 = src; src = dst; dst = tmp;
  }
  workgroupBarrier();
  for (var idx: u32 = tid; idx < NZ_; idx = idx + 32u) { dat[base + idx * NMP_] = buf[src + idx]; }
}

